SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST('1.005' AS DECIMAL(5,2));
SELECT CAST('123.456' AS DECIMAL(4,1));
SELECT CAST('abc' AS DECIMAL(5,2));
SELECT CAST('-0.005' AS DECIMAL(5,2));

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT '9223372036854775807' = 9223372036854775807;
SELECT '9223372036854775807' = 9223372036854775806;
SELECT CAST('9223372036854775807' AS SIGNED) = 9223372036854775806;

SET time_zone = '+03:00';
SET autocommit = 1;
SET SESSION session_track_state_change = ON;
SET @conformity_v = 1;
USE `public`;

SELEC 1;
SELECT * FROM conformity_no_such_table_x;
SELECT 1 AS still_alive;

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT 1 / 3;
SELECT 1 / 0;
SELECT 7 DIV 2;
SELECT 1.0 / 3;
SELECT 2 / 3e0;

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CONCAT(1.50, '');
SELECT CONCAT(1e0, '');
SELECT CONCAT(-0.0, '');
SELECT CONCAT(0.1e0 + 0.2e0, '');

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST(DATE '2024-02-29' AS DATETIME);
SELECT DATE '2024-02-29' + INTERVAL 1 SECOND;

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST('2024-02-29 13:45:30' AS DATETIME);
SELECT CAST('2024-02-29 13:45:30.5' AS DATETIME);
SELECT CAST('2024-02-29 13:45:30.1234567' AS DATETIME(6));
SELECT CAST('2024-02-29T13:45:30' AS DATETIME);
SELECT CAST('2024-02-30 00:00:00' AS DATETIME);

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST('abcdef' AS CHAR(3));
SELECT CAST(42 AS CHAR);
SELECT CAST(1.50 AS CHAR);
SELECT CAST(1e0 AS CHAR);

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST(1.5 AS SIGNED);
SELECT CAST(-1.5 AS SIGNED);
SELECT CAST(2.5 AS SIGNED);
SELECT CAST(0.5 AS SIGNED);
SELECT CAST(9223372036854775807.5 AS SIGNED);

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST(1 AS UNSIGNED);
SELECT CAST(-1 AS UNSIGNED);

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT CAST('{"b": 1, "a": 2}' AS JSON);
SELECT CAST(1 AS JSON);
SELECT CAST('x' AS JSON);

SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SELECT _utf8mb4'a' COLLATE utf8mb4_bin = _utf8mb4'a ';
SELECT _utf8mb4'a' COLLATE utf8mb4_general_ci = _utf8mb4'a ';
SELECT _utf8mb4'a' COLLATE utf8mb4_0900_bin = _utf8mb4'a ';
